{
  "source_poem_zh": "十年生死两茫茫，\n不思量，自难忘。\n千里孤坟，无处话凄凉。",
  "critical_units": [
    {
      "id": "song_01_u1",
      "source_span": "十年生死两茫茫",
      "meaning": "以十年和生死相隔概括漫长离别。"
    },
    {
      "id": "song_01_u2",
      "source_span": "不思量，自难忘",
      "meaning": "有意不去想与自然无法忘却并置。"
    },
    {
      "id": "song_01_u3",
      "source_span": "千里孤坟",
      "meaning": "以远隔千里的孤坟具体化生死距离。"
    },
    {
      "id": "song_01_u4",
      "source_span": "无处话凄凉",
      "meaning": "表达凄凉无从倾诉，未限定倾诉地点或对象。"
    }
  ],
  "translations_to_score": [
    {
      "opaque_id": "xba1d6639348555",
      "translation": "Ten years—living and dead, each lost in mist;\nI do not think of you, yet I cannot forget.\nYour lonely grave, a thousand miles away—\nNowhere to speak of this desolation.",
      "notes": []
    },
    {
      "opaque_id": "x788cb3bb0f8107",
      "translation": "Ten years apart in life and death—\nboth lost in a vastness beyond knowing.\nI do not summon you to mind;\nyet I cannot forget.\nA lonely grave, a thousand miles away—\nnowhere to speak of this desolation.",
      "notes": []
    },
    {
      "opaque_id": "xa55f08c85a5aaa",
      "translation": "Ten years—between life and death, we are lost to each other.\nI try not to think of you, yet cannot forget.\nYour lonely grave, a thousand miles away—\nnowhere to speak of this desolation.",
      "notes": []
    },
    {
      "opaque_id": "xae6c5c18d7d984",
      "translation": "Ten years—life and death, each lost to the other.\nI do not dwell on you;\nyet cannot forget.\nA thousand miles away, a solitary grave—\nnowhere to speak this desolation.",
      "notes": []
    },
    {
      "opaque_id": "xbeae144233944f",
      "translation": "Ten years—alive or dead, we are lost in vastness;\nI do not think of you, yet cannot forget.\nA thousand miles away, your lonely grave—\nnowhere to speak of this desolation.",
      "notes": []
    },
    {
      "opaque_id": "x2079e8d7d8fa00",
      "translation": "Ten years, the living and the dead lost to each other.\nI do not dwell on you, yet cannot forget.\nA thousand miles away, your lonely grave—\nnowhere to speak of all this sorrow.",
      "notes": []
    }
  ]
}

